<script setup lang="ts">
import { computed, ref, watch, onBeforeUnmount } from 'vue'
import { request, query, session, type Page } from '../api'
import { dateTime } from '../domain.js'
import Modal from './Modal.vue'
import StatusBadge from './StatusBadge.vue'
const props=defineProps<{mode:'appointments'|'conversations'|'feedback'|'notifications'}>()
const titles={appointments:'带看预约',conversations:'咨询会话',feedback:'意见反馈',notifications:'消息通知'}
const rows=ref<any[]>([]),total=ref(0),page=ref(1),loading=ref(false),busy=ref(false),error=ref(''),current=ref<any>(null),status=ref('confirmed'),notes=ref(''),messages=ref<any[]>([]),content=ref(''),clientId=ref(''),success=ref(''),feedbackReply=ref('')
const title=computed(()=>titles[props.mode])
let timer:ReturnType<typeof setInterval>|undefined,sequence=0
async function load(){const key=++sequence;loading.value=true;error.value='';try{const result=await request<Page>('/'+props.mode+query({page:page.value,page_size:10}));if(key===sequence){rows.value=result.items;total.value=result.total}}catch(err){if(key===sequence)error.value=(err as Error).message}finally{if(key===sequence)loading.value=false}}
async function loadMessages(){if(!current.value||props.mode!=='conversations')return;try{const endpoint=`/conversations/${current.value.id}/messages`;const result=await request<Page>(endpoint+'?page_size=100');if(result.total>100){const last=Math.ceil(result.total/100);const tail=await Promise.all([request<Page>(endpoint+query({page:last-1,page_size:100})),request<Page>(endpoint+query({page:last,page_size:100}))]);messages.value=tail.flatMap(part=>part.items).slice(-100)}else messages.value=result.items;await request(`/conversations/${current.value.id}/read`,{method:'POST',body:'{}'})}catch(err){error.value=(err as Error).message}}
async function open(row:any){current.value=row;notes.value=row.notes||'';feedbackReply.value=row.payload?.reply||'';status.value=row.status==='confirmed'?'completed':'confirmed';error.value='';messages.value=[];content.value='';clientId.value='';if(props.mode==='conversations')await loadMessages();if(props.mode==='notifications'&&!row.read_at){try{await request(`/notifications/${row.id}/read`,{method:'POST',body:'{}'});row.read_at=Math.floor(Date.now()/1000)}catch(err){error.value=(err as Error).message}}}
async function update(){if(busy.value||!current.value)return;busy.value=true;error.value='';try{await request(`/appointments/${current.value.id}`,{method:'PATCH',body:JSON.stringify({status:status.value,notes:notes.value})});current.value=null;success.value='预约处理结果已保存';await load()}catch(err){error.value=(err as Error).message}finally{busy.value=false}}
async function send(){if(busy.value||!content.value.trim()||!current.value)return;busy.value=true;error.value='';try{if(!clientId.value)clientId.value=crypto.randomUUID();await request(`/conversations/${current.value.id}/messages`,{method:'POST',body:JSON.stringify({client_id:clientId.value,content:content.value.trim()})});clientId.value='';content.value='';await loadMessages()}catch(err){error.value=(err as Error).message}finally{busy.value=false}}
async function replyFeedback(){if(busy.value||!current.value)return;busy.value=true;error.value='';try{await request(`/feedback/${current.value.id}/reply`,{method:'POST',body:JSON.stringify({reply:feedbackReply.value})});current.value=null;success.value='反馈回复已保存，用户将收到站内通知。';await load()}catch(err){error.value=(err as Error).message}finally{busy.value=false}}
function sender(message:any){if(message.sender_id===session.user?.id)return'我';return current.value?.members?.find((member:any)=>member.id===message.sender_id)?.nickname||`用户 #${message.sender_id}`}
watch(()=>props.mode,()=>{if(timer)clearInterval(timer);page.value=1;current.value=null;success.value='';load();if(props.mode==='conversations')timer=setInterval(()=>{if(document.visibilityState==='visible'&&current.value&&!busy.value)loadMessages()},5000)},{immediate:true})
onBeforeUnmount(()=>{if(timer)clearInterval(timer);sequence++})
</script>
<template>
  <div class="page-heading"><div><h1>{{ title }}</h1><p>{{ mode==='appointments'?'确认预约、记录带看及取消；仅显示当前组织授权范围。':mode==='conversations'?'查看本人参与的咨询，订单会话同时校验订单权限。':mode==='feedback'?'查看用户反馈、提交官方回复并记录处理结果。':'查看当前账号的站内消息。' }}</p></div><button class="button" @click="load">刷新列表</button></div><p v-if="error&&!current" class="notice danger" role="alert">{{ error }}</p><p v-if="success" class="notice success" role="status">{{ success }}</p>
  <section class="panel"><div class="filter-bar"><span class="record-count">共 {{ total }} 条记录</span></div><div class="table-scroll"><table><thead><tr><th>编号</th><template v-if="mode==='appointments'"><th>客户 / 经纪人</th><th>船型</th><th>预约时间</th><th>状态</th><th>带看备注</th></template><template v-else-if="mode==='conversations'"><th>参与人员</th><th>关联订单</th><th>最新消息</th><th>未读</th><th>更新时间</th></template><template v-else><th>标题</th><th>用户 / 关联业务</th><th>内容</th><th>状态</th><th>时间</th></template><th>操作</th></tr></thead><tbody><tr v-if="loading"><td colspan="7" class="empty">正在加载…</td></tr><tr v-else-if="!rows.length"><td colspan="7" class="empty">暂无记录</td></tr><tr v-for="row in rows" v-else :key="row.id"><td>#{{ row.id }}</td><template v-if="mode==='appointments'"><td>#{{ row.customer_id }} / {{ row.broker_id?'#'+row.broker_id:'商家直接接待' }}</td><td>#{{ row.resource_id }}</td><td>{{ dateTime(row.scheduled_at) }}</td><td><StatusBadge :value="row.status" /></td><td class="cell-truncate">{{ row.notes||'—' }}</td></template><template v-else-if="mode==='conversations'"><td class="cell-title">{{ row.members?.map((member:any)=>member.nickname).join(' / ') }}</td><td>{{ row.order_id?'#'+row.order_id:'船型咨询 #'+row.resource_id }}</td><td class="cell-truncate">{{ row.last_message?.content||'暂无消息' }}</td><td>{{ row.unread_count }}</td><td>{{ dateTime(row.updated_at) }}</td></template><template v-else><td class="cell-title">{{ row.title }}</td><td>{{ mode==='feedback'?'用户 #'+row.user_id:row.object_type+' #'+row.object_id }}</td><td class="cell-truncate">{{ row.content||row.payload?.content||row.payload?.description||'—' }}</td><td>{{ mode==='notifications'?(row.read_at?'已读':'未读'):(row.status==='handled'?'已处理':'已提交') }}</td><td>{{ dateTime(row.created_at) }}</td></template><td><button class="text-button" @click="open(row)">{{ mode==='conversations'?'进入会话':mode==='appointments'?'查看与处理':'查看详情' }}</button></td></tr></tbody></table></div><div class="pagination"><span>第 {{ page }} 页</span><button class="button small" :disabled="page<=1||loading" @click="page--;load()">上一页</button><button class="button small" :disabled="page*10>=total||loading" @click="page++;load()">下一页</button></div></section>
  <Modal v-if="current" :title="`${title} #${current.id}`" wide @close="!busy&&(current=null)"><p v-if="error" class="notice danger" role="alert">{{ error }}</p><template v-if="mode==='appointments'"><dl class="detail-grid"><dt>预约时间</dt><dd>{{ dateTime(current.scheduled_at) }}</dd><dt>客户 / 船型</dt><dd>#{{ current.customer_id }} / #{{ current.resource_id }}</dd><dt>当前状态</dt><dd><StatusBadge :value="current.status" /></dd></dl><form v-if="!['completed','cancelled'].includes(current.status)" id="service-action" class="form-grid" @submit.prevent="update"><label><span>处理状态</span><select v-model="status"><option v-if="current.status==='pending'" value="confirmed">确认预约</option><option v-if="current.status==='confirmed'" value="completed">完成带看</option><option value="cancelled">取消预约</option></select></label><label class="span-all"><span>带看记录与说明</span><textarea v-model="notes" rows="5" maxlength="2000" /></label></form><p v-else class="notice">{{ current.notes||'预约已经结束。' }}</p></template><template v-else-if="mode==='conversations'"><div class="message-list"><p v-if="!messages.length" class="empty">暂无消息</p><article v-for="message in messages" :key="message.id" class="message-item" :class="{own:message.sender_id===session.user?.id}"><small>{{ sender(message) }} · {{ dateTime(message.created_at) }}</small><p>{{ message.content }}</p></article></div><form id="service-action" @submit.prevent="send"><label><span>发送消息</span><textarea v-model="content" rows="3" required maxlength="2000" @input="clientId=''" /></label></form><p class="muted">最多显示最近100条消息，保持当前页时每5秒更新。</p></template><template v-else><dl class="detail-grid"><dt>标题</dt><dd>{{ current.title }}</dd><dt>时间</dt><dd>{{ dateTime(current.created_at) }}</dd><dt>内容</dt><dd class="preserve-lines">{{ current.content||current.payload?.content||current.payload?.description||'—' }}</dd><dt v-if="current.payload?.reply">平台回复</dt><dd v-if="current.payload?.reply" class="preserve-lines">{{ current.payload.reply }}<small class="muted">{{ dateTime(current.payload.replied_at) }}</small></dd><dt v-if="current.payload?.contact">联系说明</dt><dd v-if="current.payload?.contact">{{ current.payload.contact }}</dd></dl><form v-if="mode==='feedback'&&current.status!=='handled'" id="feedback-reply" style="margin-top:22px" @submit.prevent="replyFeedback"><label><span>平台回复与处理说明 *</span><textarea v-model="feedbackReply" required rows="4" maxlength="2000" /></label></form></template><template #footer><button class="button" :disabled="busy" @click="current=null">关闭</button><button v-if="mode==='feedback'&&current.status!=='handled'" class="button primary" :disabled="busy" form="feedback-reply">{{ busy?'正在回复…':'回复并完成处理' }}</button><button v-if="mode==='conversations'" class="button" @click="loadMessages">刷新消息</button><button v-if="mode==='conversations'||(mode==='appointments'&&!['completed','cancelled'].includes(current.status))" class="button primary" form="service-action" :disabled="busy">{{ busy?'正在提交…':mode==='conversations'?'发送消息':'保存处理结果' }}</button></template></Modal>
</template>
